import{_ as s,o as e,c as n,a2 as l}from"./chunks/framework.C2TvIV46.js";const m=JSON.parse('{"title":"構文とファイル形式","description":"","frontmatter":{},"headers":[],"relativePath":"ja/language/syntax.md","filePath":"ja/language/syntax.md"}'),t={name:"ja/language/syntax.md"};function o(p,a,c,d,i,g){return e(),n("div",null,[...a[0]||(a[0]=[l(`<h1 id="構文とファイル形式" tabindex="-1">構文とファイル形式 <a class="header-anchor" href="#構文とファイル形式" aria-label="Permalink to &quot;構文とファイル形式&quot;">​</a></h1><p>Megalo スクリプトは、<strong>要素</strong> の列からなるプレーンテキストファイル（<code>.txt</code>）です。このページでは字句規則 — トークンの作り方、コメント、ファイルの組み立て方 — を扱います。</p><h2 id="ファイル構造" tabindex="-1">ファイル構造 <a class="header-anchor" href="#ファイル構造" aria-label="Permalink to &quot;ファイル構造&quot;">​</a></h2><p>Megalo ファイルは上から下への要素の列です。必須の順序はありませんが、出荷スクリプトはだいたい次の慣習に従います。</p><ol><li><code>include</code> ディレクティブ（および任意で <code>base</code> 宣言）</li><li><code>string_table</code> / 文字列の include</li><li><code>engine_data</code>、<code>teams</code>、<code>map_permissions</code></li><li><code>map_object</code> ラベル</li><li><code>game_options</code>、<code>constants</code></li><li><code>variables</code></li><li><code>hud_widgets</code>、ロードアウト、統計</li><li><code>trigger</code> ブロック</li></ol><p>個別の要素ページはサイドバーの <strong>Elements</strong> にあります。</p><h2 id="要素モデル" tabindex="-1">要素モデル <a class="header-anchor" href="#要素モデル" aria-label="Permalink to &quot;要素モデル&quot;">​</a></h2><p>Megalo ソースは入れ子の要素として構造化されます。</p><ul><li><strong>ブロック要素</strong> はキーワードで始まり、<code>end</code> で閉じます。キーワードがその内側で許される子要素を決めます。</li><li><strong>フィールド要素</strong> はブロック内の 1 行です（親の下にインデント）。</li><li><strong>リーフ要素</strong>（<code>include</code> など）はトップレベルに単独行として現れます。</li></ul><p>合法な子要素の集合は常に親が決めます。たとえば <code>game_options</code> ブロック内では <code>option</code>、<code>override</code>、<code>player_traits</code>、<code>lock</code>、<code>hide</code> は書けますが、<code>trigger</code> や <code>variables</code> は書けません。</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">game_options</span><span class="megalo-text">                          </span><span class="megalo-comment">; block element opens</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">override</span><span class="megalo-text"> </span><span class="megalo-variable">teams_enabled</span><span class="megalo-text"> </span><span class="megalo-variable">false</span><span class="megalo-text">      </span><span class="megalo-comment">; field element</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">override</span><span class="megalo-text"> </span><span class="megalo-variable">score_to_win_round</span><span class="megalo-text"> </span><span class="megalo-number">25</span><span class="megalo-text">    </span><span class="megalo-comment">; field element</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">option</span><span class="megalo-text"> </span><span class="megalo-variable">kill_points</span><span class="megalo-text">                </span><span class="megalo-comment">; nested block element</span></span>
<span class="line"><span class="megalo-text">		option_name_kill_points</span></span>
<span class="line"><span class="megalo-text">		option_description_kill_points</span></span>
<span class="line"><span class="megalo-text">		</span><span class="megalo-number">1</span></span>
<span class="line"><span class="megalo-text">		</span><span class="megalo-number">0</span><span class="megalo-text"> points_0 </span><span class="megalo-string">&quot;&quot;</span></span>
<span class="line"><span class="megalo-text">		</span><span class="megalo-number">1</span><span class="megalo-text"> points_1 </span><span class="megalo-string">&quot;&quot;</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">end</span><span class="megalo-text">                               </span><span class="megalo-comment">; closes option</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">player_traits</span><span class="megalo-text"> </span><span class="megalo-variable">leader_traits</span><span class="megalo-text">       </span><span class="megalo-comment">; nested block element</span></span>
<span class="line"><span class="megalo-text">		leader_traits_name leader_traits_description</span></span>
<span class="line"><span class="megalo-text">		</span><span class="megalo-parameter">waypoint</span><span class="megalo-text"> </span><span class="megalo-enumMember">unchanged</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">end</span><span class="megalo-text">                               </span><span class="megalo-comment">; closes player_traits</span></span>
<span class="line"><span class="megalo-keyword">end</span><span class="megalo-text">                                   </span><span class="megalo-comment">; closes game_options</span></span></code></pre></div><p>より小さいブロックでは、入れ子の <code>begin</code>/<code>end</code> ではなく、フラットなインデント付きフィールド一覧を使うものもあります。</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">engine_data</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-parameter">name</span><span class="megalo-text"> slayer_title</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-parameter">description</span><span class="megalo-text"> slayer_description</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-parameter">icon</span><span class="megalo-text"> k_engine_icon_slayer</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-parameter">category</span><span class="megalo-text"> slayer</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><h2 id="コメント" tabindex="-1">コメント <a class="header-anchor" href="#コメント" aria-label="Permalink to &quot;コメント&quot;">​</a></h2><p>Megalo には <strong>行コメントのみ</strong> があります。セミコロンから行末までがコメントです。</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-comment">; This is a comment.</span></span>
<span class="line"><span class="megalo-text">action set my_counter add </span><span class="megalo-number">1</span><span class="megalo-text">  </span><span class="megalo-comment">; inline comment</span></span></code></pre></div><h2 id="トークン" tabindex="-1">トークン <a class="header-anchor" href="#トークン" aria-label="Permalink to &quot;トークン&quot;">​</a></h2><p>Megalo ソースは少数の種類のトークンに分解されます。</p><table tabindex="0"><thead><tr><th>トークン</th><th>例</th></tr></thead><tbody><tr><td>識別子</td><td><code>my_counter</code>、<code>player_died</code>、<code>set_to</code></td></tr><tr><td>メンバー区切り</td><td><code>current_player.score</code> の <code>.</code></td></tr><tr><td>引用文字列</td><td><code>&quot;ctf_flag_spawn&quot;</code>、<code>&quot;Slayer&quot;</code></td></tr><tr><td>整数</td><td><code>0</code>、<code>25</code>、<code>-1</code>、<code>+1</code></td></tr><tr><td>浮動小数点</td><td><code>1.5</code>、<code>+3.5</code></td></tr><tr><td>コメント</td><td><code>; ...</code></td></tr></tbody></table><h2 id="文字列リテラル" tabindex="-1">文字列リテラル <a class="header-anchor" href="#文字列リテラル" aria-label="Permalink to &quot;文字列リテラル&quot;">​</a></h2><p>二重引用符の文字列は次のエスケープをサポートします。</p><table tabindex="0"><thead><tr><th>エスケープ</th><th>意味</th></tr></thead><tbody><tr><td><code>\\n</code></td><td>改行</td></tr><tr><td><code>\\r</code></td><td>キャリッジリターン</td></tr><tr><td><code>\\t</code></td><td>タブ</td></tr><tr><td><code>\\&quot;</code></td><td>リテラルの引用符</td></tr><tr><td><code>\\\\</code></td><td>リテラルのバックスラッシュ</td></tr></tbody></table><p>それ以外の <code>\\x</code> 列は、バックスラッシュとその文字をそのまま通します。</p><p>引用文字列は Megalo の <strong>文字列リテラル</strong> です。レキサーがエスケープをデコードし、結果のテキストをコンパイラに渡します。リテラルは次の 3 つの役割でよく現れます。</p><table tabindex="0"><thead><tr><th>役割</th><th>例</th></tr></thead><tbody><tr><td>Include パス</td><td><code>include &quot;strings/slayer_strings.txt&quot;</code></td></tr><tr><td>文字列テーブルエントリ</td><td><a href="/MegaloEvolved/beta/docs/ja/language/elements/string-table"><code>string_table</code></a> 内の <code>slayer_title &quot;Slayer&quot;</code></td></tr><tr><td>アクションのオペランド</td><td><code>action hud_post_message everyone none &quot;CTF&quot;</code></td></tr></tbody></table><h3 id="文字列テーブル記号とインラインリテラル" tabindex="-1">文字列テーブル記号とインラインリテラル <a class="header-anchor" href="#文字列テーブル記号とインラインリテラル" aria-label="Permalink to &quot;文字列テーブル記号とインラインリテラル&quot;">​</a></h3><p>出荷スクリプトのユーザー向けテキストの多くは <strong>文字列テーブル記号</strong> — ローカライズ済みエントリを指す非引用の識別子 — を使います。</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">string_table</span><span class="megalo-text"> </span><span class="megalo-enumMember">english</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-variable">slayer_title</span><span class="megalo-text"> </span><span class="megalo-string">&quot;Slayer&quot;</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-variable">slayer_description</span><span class="megalo-text"> </span><span class="megalo-string">&quot;Score points by killing players on the opposing team.&quot;</span></span>
<span class="line"><span class="megalo-keyword">end</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-keyword">engine_data</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-parameter">name</span><span class="megalo-text"> </span><span class="megalo-variable">slayer_title</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-parameter">description</span><span class="megalo-text"> </span><span class="megalo-variable">slayer_description</span></span>
<span class="line"><span class="megalo-keyword">end</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-keyword">trigger</span><span class="megalo-text"> </span><span class="megalo-enumMember">general</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">action </span><span class="megalo-function">hud_post_message</span><span class="megalo-text"> </span><span class="megalo-enumMember">everyone</span><span class="megalo-text"> </span><span class="megalo-variable">none</span><span class="megalo-text"> invasion_title_spartan</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><p><code>string_table</code> ブロックが言語ごとにリテラルテキストを一度定義します。それ以外では、引用テキストを繰り返さず記号（<code>slayer_title</code>、<code>invasion_title_spartan</code>）を参照します。これによりゲームタイプ名、HUD 文字列、目標文をローカライズしやすくなります。</p><p>一部のアクションオペランドは代わりに <strong>インラインリテラル</strong> — トリガーに直接埋め込んだ引用テキスト — を受け付けます。</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-text">action hud_post_message everyone none </span><span class="megalo-string">&quot;CTF&quot;</span></span>
<span class="line"><span class="megalo-text">action hud_widget_set_text watermark </span><span class="megalo-string">&quot;Environment Artist&quot;</span></span></code></pre></div><p>コンパイラはインラインリテラルのテキストをコンパイル時にバリアントのスクリプト文字列テーブルへ格納します。インラインリテラルは <strong>ローカライズできません</strong> — 引用テキストはコンパイル時点で固定です。<a href="/MegaloEvolved/beta/docs/ja/language/compiler-settings#string-literal-strictness">厳格なコンパイラ設定</a> では、文字列テーブル記号が期待される箇所でのリテラルは禁止されます。開発中（使い捨てメッセージ、ツール用スクリプト、<code>%n</code> 書式文字列）には便利ですが、ゲームタイプを仕上げるときは <code>string_table</code> 記号を優先してください。</p><h3 id="書式プレースホルダ" tabindex="-1">書式プレースホルダ <a class="header-anchor" href="#書式プレースホルダ" aria-label="Permalink to &quot;書式プレースホルダ&quot;">​</a></h3><p>いくつかの文字列オペランドは <a href="/MegaloEvolved/beta/docs/ja/language/enums/dynamic-strings">動的文字列</a> です。テキストに <code>%</code> プレースホルダ（<code>%n</code>、<code>%p</code>、<code>%t</code>、<code>%o</code>、<code>%s</code>）を含められ、対応する参照オペランドが文字列の後に続きます。</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-text">action player_set_objective current_player </span><span class="megalo-string">&quot;+</span><span class="megalo-regexp">%n</span><span class="megalo-string">&quot;</span><span class="megalo-text"> score_to_win_round</span></span></code></pre></div><p>実行時にエンジンがプレイヤーのスコア上限を <code>%n</code> スロットに代入し、<code>+25</code> のようなテキストになります。プレースホルダ表、制限、使用するアクションは <a href="/MegaloEvolved/beta/docs/ja/language/enums/dynamic-strings">動的文字列</a> を参照。</p><h3 id="厳格コンパイラ" tabindex="-1">厳格コンパイラ <a class="header-anchor" href="#厳格コンパイラ" aria-label="Permalink to &quot;厳格コンパイラ&quot;">​</a></h3><p>多くのフィールドはリテラルではなく文字列テーブルの <strong>記号</strong> を期待します。たとえば <code>engine_data name slayer_title</code> は普通ですが、<code>engine_data name &quot;Slayer&quot;</code> は MegaloEdit ではコンパイルできても、内部ビルドファームでは拒否される旨の警告が出ます。<a href="/MegaloEvolved/beta/docs/ja/language/compiler-settings#string-literal-strictness">文字列リテラルの厳格さ</a> を参照。</p><p>アクションや条件での文字列オペランドの解決については <a href="/MegaloEvolved/beta/docs/ja/language/references#string-table-references">文字列テーブル参照</a> も参照。</p><h2 id="識別子と命名" tabindex="-1">識別子と命名 <a class="header-anchor" href="#識別子と命名" aria-label="Permalink to &quot;識別子と命名&quot;">​</a></h2><p>変数、定数、トリガー、要素の名前について:</p><ul><li>英数字とアンダースコアを含められる</li><li>数字で <strong>始めてはならない</strong></li><li>共有名前空間で <strong>一意</strong> でなければならない（変数、定数、トリガー、ゲームオプション、その他の名前付き要素は衝突できない）</li></ul><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">variables</span><span class="megalo-text"> </span><span class="megalo-keyword">global</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-modifier">local</span><span class="megalo-text"> </span><span class="megalo-type">number</span><span class="megalo-text"> </span><span class="megalo-variable">red_score</span><span class="megalo-text"> </span><span class="megalo-number">0</span><span class="megalo-text">       </span><span class="megalo-comment">; valid</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-modifier">local</span><span class="megalo-text"> </span><span class="megalo-type">number</span><span class="megalo-text"> </span><span class="megalo-variable">team3_score</span><span class="megalo-text"> </span><span class="megalo-number">0</span><span class="megalo-text">     </span><span class="megalo-comment">; valid</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-modifier">local</span><span class="megalo-text"> </span><span class="megalo-type">number</span><span class="megalo-text"> 4team_score </span><span class="megalo-number">0</span><span class="megalo-text">     </span><span class="megalo-comment">; invalid — starts with a digit</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><h2 id="includes" tabindex="-1">Includes <a class="header-anchor" href="#includes" aria-label="Permalink to &quot;Includes&quot;">​</a></h2><p><code>include</code> ディレクティブは、コンパイル時に別のソースファイルを現在のスクリプトへマージします。</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">include</span><span class="megalo-text"> </span><span class="megalo-string">&quot;strings/slayer_strings.txt&quot;</span></span>
<span class="line"><span class="megalo-keyword">include</span><span class="megalo-text"> </span><span class="megalo-string">&quot;includes/multiplayer_loadouts.txt&quot;</span></span>
<span class="line"><span class="megalo-keyword">include</span><span class="megalo-text"> </span><span class="megalo-string">&quot;includes/sudden_death_pre.txt&quot;</span></span></code></pre></div><p>インクルードされたファイルはその要素を最終スクリプトに寄与します。Bungie がロードアウト、サドンデス、実績などの共通ロジックを多くのゲームタイプで共有した方法です。</p><p>同じスクリプト内で既にインクルードされたパスはスキップされます（一度だけ解決）。サイクルを含む詳細は <a href="/MegaloEvolved/beta/docs/ja/language/elements/include"><code>include</code></a> を参照。</p><p>文字列テーブルは、言語非依存のラッパーが言語ごとのファイルを include する形でよく整理されます。</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">include</span><span class="megalo-text"> </span><span class="megalo-string">&quot;strings/common_strings.txt&quot;</span></span></code></pre></div><p><code>strings/common_strings.txt</code> 自体は、言語ごとに 1 行のプレーンな include の一覧です。</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">include</span><span class="megalo-text"> </span><span class="megalo-string">&quot;english/common_strings.txt&quot;</span></span>
<span class="line"><span class="megalo-keyword">include</span><span class="megalo-text"> </span><span class="megalo-string">&quot;french/common_strings.txt&quot;</span></span>
<span class="line"><span class="megalo-keyword">include</span><span class="megalo-text"> </span><span class="megalo-string">&quot;german/common_strings.txt&quot;</span></span></code></pre></div><p>各言語ファイルは <code>string_table &lt;language&gt;</code> で始まり、そのロケール向けの翻訳文字列を定義します。</p><h3 id="localized-include" tabindex="-1">localized_include <a class="header-anchor" href="#localized-include" aria-label="Permalink to &quot;localized_include&quot;">​</a></h3><p>MegaloEdit は 2 つ目の include キーワードを認識します。</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">localized_include</span><span class="megalo-text"> </span><span class="megalo-string">&quot;strings/english/slayer_strings.txt&quot;</span></span></code></pre></div><p>構文は <code>include</code> と同じ — 現在のファイルからの相対パスを引用符で囲みます。</p><p>ローカライズ include は通常の include と同様ですが、寛容コンパイルモードではファイルが欠けていても <strong>省略可能</strong> です。コンパイラがパスを見つけられない場合、警告を出して include をスキップし、コンパイルは失敗しません。プレーンな <code>include</code> で欠けたファイルは常にハードエラーです。</p><p>厳格コンパイルモードでは、欠けたローカライズ include も同様にエラーになります。MegaloEdit は常に寛容モードを使います — <a href="/MegaloEvolved/beta/docs/ja/language/compiler-settings">コンパイラ設定</a> を参照。</p><p>ファイルが <strong>存在する</strong> 場合、<code>localized_include</code> は <code>include</code> と同じく読み込み・パースします。このキーワードはコンパイル済みバリアントデータには残らず、コンパイル時にすべて解決されます。</p><p><strong>出荷された HREK スクリプトでは使われていません。</strong> Bungie は代わりにラッパーファイルとプレーンな <code>include</code> を使いました（上記参照）。Reach スクリプティングでは、そのラッパーパターンが正式なやり方です。</p><h2 id="ベースファイル" tabindex="-1">ベースファイル <a class="header-anchor" href="#ベースファイル" aria-label="Permalink to &quot;ベースファイル&quot;">​</a></h2><p>一部のスクリプトは include の代わりに（または併用して）<code>base</code> ディレクティブで始まります。</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">base</span><span class="megalo-text"> </span><span class="megalo-string">&quot;ctf.mglo&quot;</span></span></code></pre></div><p>これはソーステキストをマージするのではなく、コンパイル済み親バリアントを継承します。詳しくは <a href="/MegaloEvolved/beta/docs/ja/language/base-files">ベースファイル</a> を参照。</p><h2 id="インデント" tabindex="-1">インデント <a class="header-anchor" href="#インデント" aria-label="Permalink to &quot;インデント&quot;">​</a></h2><p>Megalo はブロック要素内のインデントにタブを使います。インデントは見た目用で — パーサーは構造を空白ではなくキーワード（<code>end</code>、要素名）で判定します。出荷スクリプトは一貫してタブを使います。</p><h2 id="関連項目" tabindex="-1">関連項目 <a class="header-anchor" href="#関連項目" aria-label="Permalink to &quot;関連項目&quot;">​</a></h2><ul><li><a href="/MegaloEvolved/beta/docs/ja/language/elements/string-table">string_table</a> — ローカライズ文字列の定義</li><li><a href="/MegaloEvolved/beta/docs/ja/language/compiler-settings">コンパイラ設定</a> — MegaloEdit のコンパイルフラグ（<code>enforceLocalizedIncludes</code> など）</li><li><a href="/MegaloEvolved/beta/docs/ja/language/base-files">ベースファイル</a> — コンパイル済みバリアントからの継承</li><li><a href="/MegaloEvolved/beta/docs/ja/language/examples">サンプルスクリプト</a> — 注釈付きの最小スクリプト</li><li><a href="/MegaloEvolved/beta/docs/ja/language/references#string-table-references">参照</a> — アクション内の文字列オペランド</li></ul>`,69)])])}const u=s(t,[["render",o]]);export{m as __pageData,u as default};
